CREATE TABLE projects(id INTEGER PRIMARY KEY, name TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0);
CREATE TABLE tasks(id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id), title TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', priority INTEGER NOT NULL DEFAULT 3, assignee TEXT);
CREATE TABLE comments(id INTEGER PRIMARY KEY, task_id INTEGER NOT NULL REFERENCES tasks(id), author TEXT NOT NULL, body TEXT NOT NULL);
